[CmdletBinding(SupportsShouldProcess=$true)]
param(
    [ValidateSet('Start','Continue','Status','Summarize','Stop')][string]$Action='Status',
    [ValidateRange(1,20)][int]$RunsPerArm=5,
    [ValidateRange(30,600)][int]$SampleSeconds=120,
    [ValidateRange(1,10)][int]$SampleIntervalSeconds=2,
    [switch]$AllowAutomaticReboot,
    [string]$EvidenceRoot="$PSScriptRoot\lab-evidence",
    [string]$RunDirectory,
    [string]$ProviderPath="$PSScriptRoot\..\..\controller\providers\Microsoft365RunDemandLaunch.ps1"
)

Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
$TaskName='Lacksan-EXP-124-LabHarness'
$ActivePointer=Join-Path $EvidenceRoot 'active.json'

function Test-Elevation {
    $p=New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
    if(-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Elevation required.'}
}
function Ensure-Directory([string]$Path){if(-not(Test-Path -LiteralPath $Path)){New-Item -ItemType Directory -Path $Path -Force|Out-Null}}
function Write-Json([string]$Path,$Value){$Value|ConvertTo-Json -Depth 16|Set-Content -LiteralPath $Path -Encoding UTF8}
function Read-Json([string]$Path){if(-not(Test-Path -LiteralPath $Path)){throw "Required state missing: $Path"};Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json}
function Get-BootUtc {((Get-CimInstance Win32_OperatingSystem).LastBootUpTime).ToUniversalTime()}
function Get-Median($Values){$v=@($Values|Where-Object{$null-ne$_}|ForEach-Object{[double]$_}|Sort-Object);if($v.Count-eq0){return $null};$m=[int][math]::Floor($v.Count/2);if($v.Count%2){return [double]$v[$m]};([double]$v[$m-1]+[double]$v[$m])/2}
function Get-Mad($Values){$v=@($Values|Where-Object{$null-ne$_}|ForEach-Object{[double]$_});if($v.Count-eq0){return $null};$median=Get-Median $v;Get-Median @($v|ForEach-Object{[math]::Abs($_-$median)})}
function Get-Paths([string]$Dir){[pscustomobject]@{State=(Join-Path $Dir 'harness-state.json');ProviderState=(Join-Path $Dir 'provider-state.json');ProviderLog=(Join-Path $Dir 'provider-events.jsonl');Summary=(Join-Path $Dir 'summary.json')}}
function Resolve-RunDirectory {if($RunDirectory){return (Resolve-Path -LiteralPath $RunDirectory).Path};$a=Read-Json $ActivePointer;if(-not$a.runDirectory){throw 'Active run pointer invalid.'};(Resolve-Path -LiteralPath ([string]$a.runDirectory)).Path}
function Write-LabLog([string]$Dir,[string]$Event,[hashtable]$Data){$row=[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment='EXP-124';component='lab-harness';action=$Action;event=$Event;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;data=$Data};($row|ConvertTo-Json -Compress -Depth 12)|Add-Content -LiteralPath (Join-Path $Dir 'lab-events.jsonl') -Encoding UTF8}
function Invoke-Provider([string]$ProviderAction,[string]$Dir,[switch]$WhatIfOnly){$p=Get-Paths $Dir;$args=@{Action=$ProviderAction;StatePath=$p.ProviderState;LogPath=$p.ProviderLog};if($WhatIfOnly){& $ProviderPath @args -WhatIf}else{& $ProviderPath @args}}
function Get-ResumeTask {Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue}
function Register-ResumeTask([string]$Dir){if(Get-ResumeTask){throw "Scheduled task already exists: $TaskName"};$exe=(Get-Command powershell.exe -ErrorAction Stop).Source;$args="-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`" -Action Continue -RunDirectory `"$Dir`" -EvidenceRoot `"$EvidenceRoot`" -ProviderPath `"$ProviderPath`"";$a=New-ScheduledTaskAction -Execute $exe -Argument $args;$user=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$t=New-ScheduledTaskTrigger -AtLogOn -User $user;$pr=New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest;$s=New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 20);if($PSCmdlet.ShouldProcess($TaskName,'Register reversible reboot continuation task')){Register-ScheduledTask -TaskName $TaskName -Action $a -Trigger $t -Principal $pr -Settings $s|Out-Null}}
function Remove-ResumeTask([string]$Dir){if(Get-ResumeTask){if($PSCmdlet.ShouldProcess($TaskName,'Remove reboot continuation task')){Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false;Write-LabLog $Dir 'continuation-task-removed' @{task=$TaskName}}}}
function Get-ProtectedSnapshot {
    $services=@();foreach($n in 'WinDefend','mpssvc','wuauserv','UsoSvc','BITS','ClickToRunSvc','Tailscale','TermService'){try{$s=Get-Service $n -ErrorAction Stop;$services+=[pscustomobject]@{name=$n;status=$s.Status.ToString();startType=$s.StartType.ToString()}}catch{$services+=[pscustomobject]@{name=$n;status='absent';startType=$null}}}
    $processes=@(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName-match'(?i)omnissa|horizon|msrdc|mstsc|tailscale|windowsapp'}|Select-Object ProcessName,Id,Responding)
    [pscustomobject]@{services=$services;processes=$processes}
}
function Get-RegistrationState($ProviderState){$path=[string]$ProviderState.entry.Path;$name=[string]$ProviderState.entry.Name;if(-not(Test-Path -LiteralPath $path)){return [pscustomobject]@{present=$false;kind=$null;data=$null}};$k=Get-Item -LiteralPath $path;if(-not($k.GetValueNames()-contains$name)){return [pscustomobject]@{present=$false;kind=$null;data=$null}};[pscustomobject]@{present=$true;kind=$k.GetValueKind($name).ToString();data=[string]$k.GetValue($name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)}
function Assert-BaselineRegistration($ProviderState){$r=Get-RegistrationState $ProviderState;if(-not$r.present-or$r.kind-ne[string]$ProviderState.entry.Kind-or$r.data-ne[string]$ProviderState.entry.Data){throw 'Baseline Microsoft 365 Run registration drift detected.'}}
function Assert-TreatmentRegistration($ProviderState){$r=Get-RegistrationState $ProviderState;if($r.present){throw 'Treatment Microsoft 365 Run registration reappeared.'}}
function Get-SystemSample {$cpu=(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'").PercentProcessorTime;$disk=(Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'").DiskBytesPersec;[pscustomobject]@{cpu=[double]$cpu;disk=[double]$disk}}
function Get-TargetProcessSample([string]$Executable){$leaf=[IO.Path]::GetFileName($Executable);$rows=@();foreach($w in @(Get-CimInstance Win32_Process -Filter "Name='$leaf'" -ErrorAction SilentlyContinue)){if(-not$w.ExecutablePath-or[IO.Path]::GetFullPath([string]$w.ExecutablePath)-ne[IO.Path]::GetFullPath($Executable)){continue};$p=Get-Process -Id ([int]$w.ProcessId) -ErrorAction SilentlyContinue;if($p){$rows+=[pscustomobject]@{pid=[int]$w.ProcessId;cpuMs=[double]$p.TotalProcessorTime.TotalMilliseconds;workingSetBytes=[int64]$p.WorkingSet64;readBytes=[uint64]$w.ReadTransferCount;writeBytes=[uint64]$w.WriteTransferCount}}};$rows}
function Collect-Trial([string]$Phase,[int]$Ordinal,[string]$Dir,$ProviderState){
    $boot=Get-BootUtc;$protectedBefore=Get-ProtectedSnapshot;$collectorBefore=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$system=@();$target=@();$count=[int][math]::Ceiling($SampleSeconds/[double]$SampleIntervalSeconds)
    for($i=0;$i-lt$count;$i++){$system+=Get-SystemSample;$target+=@(Get-TargetProcessSample ([string]$ProviderState.entry.Executable.Path)|ForEach-Object{[pscustomobject]@{sample=$i;pid=$_.pid;cpuMs=$_.cpuMs;workingSetBytes=$_.workingSetBytes;readBytes=$_.readBytes;writeBytes=$_.writeBytes}});if($i-lt$count-1){Start-Sleep -Seconds $SampleIntervalSeconds}}
    $collectorAfter=[double](Get-Process -Id $PID).TotalProcessorTime.TotalMilliseconds;$explorer=Get-Process explorer -ErrorAction SilentlyContinue|Sort-Object StartTime|Select-Object -First 1;$targetPids=@($target|Select-Object -ExpandProperty pid -Unique)
    [ordered]@{schemaVersion=1;experiment='EXP-124';phase=$Phase;ordinal=$Ordinal;machine=$env:COMPUTERNAME;bootUtc=$boot.ToString('o');capturedUtc=(Get-Date).ToUniversalTime().ToString('o');registration=(Get-RegistrationState $ProviderState);desktopProxy=[ordered]@{explorerPresent=[bool]$explorer;explorerResponding=if($explorer){[bool]$explorer.Responding}else{$false};bootToExplorerStartMs=if($explorer){($explorer.StartTime.ToUniversalTime()-$boot).TotalMilliseconds}else{$null}};system=[ordered]@{cpuMedianPercent=(Get-Median @($system|ForEach-Object{$_.cpu}));cpuMadPercent=(Get-Mad @($system|ForEach-Object{$_.cpu}));diskMedianBytesPerSec=(Get-Median @($system|ForEach-Object{$_.disk}));diskMadBytesPerSec=(Get-Mad @($system|ForEach-Object{$_.disk}))};targetProcess=[ordered]@{executable=[string]$ProviderState.entry.Executable.Path;observed=($target.Count-gt0);pids=$targetPids;peakWorkingSetBytes=if($target.Count){($target|Measure-Object workingSetBytes -Maximum).Maximum}else{$null};maxObservedCpuMs=if($target.Count){($target|Measure-Object cpuMs -Maximum).Maximum}else{$null};maxObservedReadBytes=if($target.Count){($target|Measure-Object readBytes -Maximum).Maximum}else{$null};maxObservedWriteBytes=if($target.Count){($target|Measure-Object writeBytes -Maximum).Maximum}else{$null}};protected=[ordered]@{before=$protectedBefore;after=(Get-ProtectedSnapshot)};functionalEvidence=[ordered]@{manualOfficeLaunch='needs-evidence';clickToRunServicing='needs-evidence';activationDocumentsAddins='needs-evidence';protectedApplicationConnectionReadiness='needs-evidence'};instrumentation=[ordered]@{collectorCpuDeltaMs=($collectorAfter-$collectorBefore);sampleCount=$system.Count;sampleIntervalSeconds=$SampleIntervalSeconds}}
}
function Summarize([string]$Dir){$runs=@(Get-ChildItem $Dir -Filter 'run-*.json' -File|Sort-Object Name|ForEach-Object{Read-Json $_.FullName});if($runs.Count-eq0){throw 'No runs found.'};$groups=[ordered]@{};foreach($phase in 'Baseline','Treatment'){$g=@($runs|Where-Object{$_.phase-eq$phase});$groups[$phase]=[ordered]@{runs=$g.Count;bootToExplorerStartMs=[ordered]@{median=(Get-Median @($g|ForEach-Object{$_.desktopProxy.bootToExplorerStartMs}));mad=(Get-Mad @($g|ForEach-Object{$_.desktopProxy.bootToExplorerStartMs}))};cpuMedianPercent=[ordered]@{median=(Get-Median @($g|ForEach-Object{$_.system.cpuMedianPercent}));mad=(Get-Mad @($g|ForEach-Object{$_.system.cpuMedianPercent}))};diskMedianBytesPerSec=[ordered]@{median=(Get-Median @($g|ForEach-Object{$_.system.diskMedianBytesPerSec}));mad=(Get-Mad @($g|ForEach-Object{$_.system.diskMedianBytesPerSec}))};targetPeakWorkingSetBytes=[ordered]@{median=(Get-Median @($g|ForEach-Object{$_.targetProcess.peakWorkingSetBytes}));mad=(Get-Mad @($g|ForEach-Object{$_.targetProcess.peakWorkingSetBytes}))}}};$rollback=@($runs|Where-Object{$_.phase-eq'RollbackVerify'}|Select-Object -Last 1);$summary=[ordered]@{schemaVersion=1;experiment='EXP-124';generatedUtc=(Get-Date).ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;groups=$groups;rollbackRebootVerified=($rollback.Count-eq1-and[bool]$rollback[0].registration.present);remainingEvidence=@('Manual Microsoft 365 application launch and one controlled core-function check','Click-to-Run servicing and update readiness','Activation, documents, and add-ins verification','Timed Omnissa, Windows App, Remote Desktop, and Tailscale connection readiness','Instrumentation qualification beyond harness overhead');limitations=@('bootToExplorerStartMs is an Explorer-start readiness proxy rather than a full usable-desktop instrumentation marker','Target process samples record observed process state and do not attribute descendant processes that use different executable identities')};Write-Json (Join-Path $Dir 'summary.json') $summary;$summary}
function Reboot-IfAllowed([string]$Dir){if($AllowAutomaticReboot){Write-LabLog $Dir 'reboot-requested' @{};Restart-Computer -Force}else{Write-LabLog $Dir 'reboot-required' @{};Write-Output 'Reboot required. The continuation task resumes at the next interactive logon.'}}

Test-Elevation
if(-not(Test-Path -LiteralPath $ProviderPath)){throw 'EXP-124 provider missing.'}
switch($Action){
    'Start' {
        Ensure-Directory $EvidenceRoot;if(Test-Path -LiteralPath $ActivePointer){throw 'An active EXP-124 run already exists.'};$check=Invoke-Provider 'Check' $EvidenceRoot
        if($WhatIfPreference){$null=$PSCmdlet.ShouldProcess($TaskName,"Prepare $RunsPerArm baseline and treatment boots plus rollback verification");return $check}
        $stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMdd-HHmmss');$dir=Join-Path $EvidenceRoot $stamp;Ensure-Directory $dir;$p=Get-Paths $dir;Invoke-Provider 'Capture' $dir|Out-Null;$state=[ordered]@{schemaVersion=1;phase='Baseline';completedRuns=0;runsPerArm=$RunsPerArm;lastBootUtc=$null;sampleSeconds=$SampleSeconds;sampleIntervalSeconds=$SampleIntervalSeconds};Write-Json $p.State $state;Write-Json $ActivePointer @{runDirectory=$dir};Register-ResumeTask $dir;Write-LabLog $dir 'started' @{runsPerArm=$RunsPerArm;sampleSeconds=$SampleSeconds};Reboot-IfAllowed $dir
    }
    'Continue' {
        $dir=Resolve-RunDirectory;$p=Get-Paths $dir;$state=Read-Json $p.State;$providerState=Read-Json $p.ProviderState;$boot=(Get-BootUtc).ToString('o');if($state.lastBootUtc-eq$boot){throw 'Duplicate collection from the same boot refused.'}
        if($state.phase-eq'Baseline'){Assert-BaselineRegistration $providerState}
        elseif($state.phase-eq'Treatment'){Invoke-Provider 'VerifyReboot' $dir|Out-Null;Assert-TreatmentRegistration $providerState}
        elseif($state.phase-eq'RollbackVerify'){Assert-BaselineRegistration $providerState;$trial=Collect-Trial 'RollbackVerify' 1 $dir $providerState;Write-Json (Join-Path $dir 'run-RollbackVerify-01.json') $trial;Summarize $dir|Out-Null;Remove-ResumeTask $dir;Remove-Item -LiteralPath $ActivePointer -Force;Write-LabLog $dir 'completed' @{rollbackRebootVerified=$true};return (Read-Json $p.Summary)}
        else{throw "Unknown harness phase: $($state.phase)"}
        $ordinal=[int]$state.completedRuns+1;$trial=Collect-Trial ([string]$state.phase) $ordinal $dir $providerState;Write-Json (Join-Path $dir ("run-{0}-{1:D2}.json" -f $state.phase,$ordinal)) $trial;$state.completedRuns=$ordinal;$state.lastBootUtc=$boot
        if($state.completedRuns-ge[int]$state.runsPerArm){if($state.phase-eq'Baseline'){$state.phase='Treatment';$state.completedRuns=0;Invoke-Provider 'Apply' $dir|Out-Null;Invoke-Provider 'Verify' $dir|Out-Null}else{Invoke-Provider 'Rollback' $dir|Out-Null;$state.phase='RollbackVerify';$state.completedRuns=0}}
        Write-Json $p.State $state;Write-LabLog $dir 'trial-collected' @{phase=$trial.phase;ordinal=$ordinal};Reboot-IfAllowed $dir
    }
    'Status' {if(Test-Path -LiteralPath $ActivePointer){$dir=Resolve-RunDirectory;Read-Json (Get-Paths $dir).State}else{[pscustomobject]@{active=$false}}}
    'Summarize' {$dir=Resolve-RunDirectory;Summarize $dir}
    'Stop' {$dir=Resolve-RunDirectory;$p=Get-Paths $dir;if(Test-Path -LiteralPath $p.ProviderState){Invoke-Provider 'Rollback' $dir|Out-Null};Remove-ResumeTask $dir;Remove-Item -LiteralPath $ActivePointer -Force -ErrorAction SilentlyContinue;Write-LabLog $dir 'stopped' @{};[pscustomobject]@{stopped=$true;runDirectory=$dir}}
}
